bool check_deadlock(int *work, int **allocation, int **request, int n, int m) {
    bool finish[n];
    memset(finish, false, sizeof(finish));

    for (int i = 0; i < n; i++) {
        if (!finish[i]) {
            bool can_alloc = true;
            for (int j = 0; j < m; j++) {
                if (request[i][j] > work[j]) {
                    can_alloc = false;
                    break;
                }
            }
            if (can_alloc) {
                // 模拟线程i完成，释放资源
                for (int j = 0; j < m; j++) {
                    work[j] += allocation[i][j];  // 关键点
                }
                finish[i] = true;
                i = -1;  // 重新扫描
            }
        }
    }

    // 检查是否所有线程都能完成
    for (int i = 0; i < n; i++) {
        if (!finish[i]) return true;  // 存在死锁
    }
    return false;
}

#define MAX_MUTEX 16
#define MAX_SEMAPHORE 16
#define TOTAL_RESOURCES (MAX_MUTEX + MAX_SEMAPHORE)

// mutex编号: 0 ~ 15
// semaphore编号: 16 ~ 31

int get_resource_idx(int id, int is_mutex) {
    if (is_mutex) return id;
    else return MAX_MUTEX + id;
}

// 在mutex_lock中调用检测
void mutex_lock(int id) {
    int idx = get_resource_idx(id, 1);
    // ... 更新Request矩阵 ...
    if (check_deadlock(available, allocation, request, n, TOTAL_RESOURCES)) {
        // 回滚Request
        return -0xDEAD;
    }
    // ... 实际获取锁 ...
    allocation[current_tid][idx]++;  // 关键点
    // ...
}

int sys_mutex_lock(int mutex_id) {
    struct proc *p = myproc();
    int tid = p->tid;
    int idx = get_mutex_idx(mutex_id);

    // LAB5: 死锁检测
    if (p->deadlock_detect) {
        // 1. 记录请求
        request[tid][idx] = 1;

        // 2. 检测
        if (check_deadlock(available, allocation, request, nthread, nresource)) {
            // 3. 检测到死锁，拒绝请求
            request[tid][idx] = 0;  // 回滚请求记录
            return -0xDEAD;
        }
    }

    // 4. 实际获取锁（可能阻塞）
    acquire(&mutex_table[mutex_id].lock);

    // 5. 更新分配矩阵
    allocation[tid][idx] = 1;
    available[idx]--;

    return 0;
}

void semaphore_down(int sem_id, int count) {
    struct proc *p = myproc();
    int idx = get_sem_idx(sem_id);

    if (p->deadlock_detect) {
        // 记录请求count个资源
        request[p->tid][idx] += count;

        // 每次down都进行完整的银行家算法检测
        if (check_deadlock(available, allocation, request, nthread, nresource)) {
            request[p->tid][idx] -= count;
            return -0xDEAD;
        }
    }

    // 实际P操作（可能阻塞）
    while (semaphore[sem_id].value < count) {
        sleep(&semaphore[sem_id], &semaphore[sem_id].lock);
    }
    semaphore[sem_id].value -= count;

    // 更新分配矩阵
    allocation[p->tid][idx] += count;
    available[idx] -= count;
    request[p->tid][idx] -= count;  // 请求已满足

    return 0;
}

